+
+it.each([
+  { explicit: false, duplicate: false }, { explicit: true, duplicate: false }, { explicit: false, duplicate: true },
+])('SSR labels name their own Root with unique stable IDs before hydration (%j)', props => {
+  const { body } = render(Labels, { props });
+  const roots = [...body.matchAll(/<div\b[^>]*role="dialog"[^>]*>([\s\S]*?)<\/div>/g)];
+  expect(roots).toHaveLength(2);
+  const ids = [...body.matchAll(/\bid="([^"]+)"/g)].map(match => match[1]);
+  expect(new Set(ids).size).toBe(ids.length);
+  roots.forEach((root, index) => {
+    const labelled = root[0].match(/aria-labelledby="([^"]+)"/)?.[1];
+    const described = root[0].match(/aria-describedby="([^"]+)"/)?.[1];
+    const titleIds = [...root[1].matchAll(/<h2\b[^>]*\bid="([^"]+)"/g)].map(match => match[1]);
+    const descriptionId = root[1].match(/<p\b[^>]*\bid="([^"]+)"/)?.[1];
+    expect(labelled).toBe(titleIds.at(-1)); expect(labelled).toBeDefined();
+    expect(described).toBe(descriptionId); expect(described).toBeDefined();
+    if (props.explicit) { expect(labelled).toBe(`title-${index}`); expect(described).toBe(`description-${index}`); }
+  });
+});
+
+it.each([{ showTitle: false, showDescription: false }, { empty: true }])('SSR omits relationships for absent or suppressed label parts (%j)', props => {
+  const { body } = render(Labels, { props });
+  expect(body).not.toContain('aria-labelledby'); expect(body).not.toContain('aria-describedby');
+  expect(body).not.toContain('<h2'); expect(body).not.toContain('<p ');
